package com.procurement.vendorquotation.controller;import com.procurement.common.response.*;import com.procurement.vendorquotation.dto.request.*;import com.procurement.vendorquotation.dto.response.*;import com.procurement.vendorquotation.service.*;import jakarta.validation.Valid;import org.springframework.data.domain.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/quotation-attachments")public class QuotationAttachmentController{private final VendorQuotationService service;public QuotationAttachmentController(VendorQuotationService s){service=s;}@PostMapping public ResponseEntity<ApiResponse<QuotationAttachmentResponse>>create(@Valid@RequestBody QuotationAttachmentRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success("Quotation attachment created",service.addAttachment(r)));}@GetMapping public ApiResponse<PageResponse<QuotationAttachmentResponse>>search(@RequestParam(required=false)Long quotationId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.success(service.attachments(quotationId,PageRequest.of(page,size)));}}
